import React, { useEffect, useMemo, useState } from 'react';
import { fetchForexIntraday, postPrediction, getIndicatorStats } from '../../shared/traidNew/api/client';
import { DEFAULT_CONFIG } from '../../shared/traidNew/config/defaults';
import {
    SMA,
    EMA,
    RSI,
    BollingerBands,
    ATR,
    MACD,
    Stochastic,
    WilliamsR,
    ADX,
    CCI,
    ROC,
    TRIX,
    MFI,
    OBV,
    IchimokuCloud,
    KeltnerChannels,
    PSAR,
} from '../../shared/traidNew/lib/indicators';
import { aggregateSignals } from '../../features/traidNew/prediction/lib/aggregateSignals';
import { postIndicatorStats } from '../../shared/traidNew/api/client';
import { AdvancedRealTimeChart } from 'react-ts-tradingview-widgets';
import './styles.css';

export default function TraidNewPage(): JSX.Element {
	const [points, setPoints] = useState<Array<{ timestamp: number; open: number; high: number; low: number; close: number }>>([]);
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState<string | null>(null);
	const [lastUpdated, setLastUpdated] = useState<number>(0);
	const [lastPredictionAt, setLastPredictionAt] = useState<number>(0);
	const [storedAccuracies, setStoredAccuracies] = useState<Record<string, number>>({});

	useEffect(() => {
		let cancelled = false;
		const load = async () => {
			try {
				setLoading(true);
				let data = await fetchForexIntraday({ symbol: DEFAULT_CONFIG.asset.symbol, interval: '1min' });
				if (data.points.length === 0) {
					data = await fetchForexIntraday({ symbol: DEFAULT_CONFIG.asset.symbol, interval: 'daily' as any });
				}
				if (!cancelled) {
					setPoints(data.points);
					setLastUpdated(Date.now());
					setError(null);
				}
			} catch (e: any) {
				setError(e?.message || 'Failed to load data');
			} finally {
				setLoading(false);
			}
		};
		load();
		// fetch stored accuracies on mount
		getIndicatorStats().then((s) => setStoredAccuracies(s?.indicators || {})).catch(() => void 0);
		// align updates to the start of each minute
		const now = Date.now();
		const delay = 60_000 - (now % 60_000);
		const timeout = setTimeout(() => {
			load();
			const id = setInterval(load, 60_000);
			// store id on window for cleanup
			( window as any ).__dashIntervalId = id;
		}, delay);
		return () => {
			cancelled = true;
			clearTimeout(timeout);
			if ((window as any).__dashIntervalId) clearInterval((window as any).__dashIntervalId);
		};
	}, []);

    const calc = useMemo(() => {
        if (points.length < 100) return null;
        const closes = points.map(p => p.close);
        const highs = points.map(p => p.high);
        const lows = points.map(p => p.low);
        const volumes = points.map(() => 0);

        const sma20 = SMA.calculate({ period: 20, values: closes });
        const ema20 = EMA.calculate({ period: 20, values: closes });
        const rsi14 = RSI.calculate({ period: 14, values: closes });
        const bb = BollingerBands.calculate({ period: 20, values: closes, stdDev: 2 });
        const atr14 = ATR.calculate({ period: 14, high: highs, low: lows, close: closes });
        const macd = MACD.calculate({ values: closes, fastPeriod: 12, slowPeriod: 26, signalPeriod: 9, SimpleMAOscillator: false, SimpleMASignal: false });
        const stoch = Stochastic.calculate({ high: highs, low: lows, close: closes, period: 14, signalPeriod: 3 });
        const wr = WilliamsR.calculate({ high: highs, low: lows, close: closes, period: 14 });
        const adx = ADX.calculate({ high: highs, low: lows, close: closes, period: 14 });
        const cci = CCI.calculate({ high: highs, low: lows, close: closes, period: 20 });
        const roc = ROC.calculate({ period: 9, values: closes });
        const trix = TRIX.calculate({ period: 15, values: closes });
        const mfi = MFI.calculate({ high: highs, low: lows, close: closes, volume: volumes, period: 14 });
        const obv = OBV.calculate({ close: closes, volume: volumes });
        const ichimoku = IchimokuCloud.calculate({ high: highs, low: lows, conversionPeriod: 9, basePeriod: 26, spanPeriod: 52, displacement: 26 });
        const kc = KeltnerChannels.calculate({ high: highs, low: lows, close: closes, maPeriod: 20, multiplier: 2, atrPeriod: 10, useSMA: false });
        const psar = PSAR.calculate({ high: highs, low: lows, step: 0.02, max: 0.2 });

        return { closes, highs, lows, sma20, ema20, rsi14, bb, atr14, macd, stoch, wr, adx, cci, roc, trix, mfi, obv, ichimoku, kc, psar };
    }, [points]);

	const prediction = useMemo(() => {
        if (!calc) return null;
        const lastClose = calc.closes[calc.closes.length - 1]!;
        const results: Array<{ indicatorId: string; signal: 'buy'|'sell'|'hold'; weight: number; value: number; confidence: number; contribution: number; }> = [];

        const add = (id: string, value: number | undefined, signal: 'buy'|'sell'|'hold', weight = 1, confidence = 1) => {
            if (value === undefined || Number.isNaN(value)) return;
            results.push({ indicatorId: id, signal, weight, value, confidence, contribution: 0 });
        };

        // Trend/Momentum
        add('EMA20_vs_SMA20', lastClose, calc.ema20[calc.ema20.length - 1]! > calc.sma20[calc.sma20.length - 1]! ? 'buy' : 'sell');
        const rsiLast = calc.rsi14[calc.rsi14.length - 1]!; add('RSI14', rsiLast, rsiLast < 30 ? 'buy' : rsiLast > 70 ? 'sell' : 'hold');
        const macdLast = calc.macd[calc.macd.length - 1]; if (macdLast && macdLast.MACD !== undefined && macdLast.signal !== undefined) add('MACD', macdLast.MACD - macdLast.signal, macdLast.MACD > macdLast.signal ? 'buy' : 'sell');
        const stochLast = calc.stoch[calc.stoch.length - 1]; if (stochLast) add('Stochastic', stochLast.k - stochLast.d, stochLast.k > stochLast.d ? 'buy' : 'sell');
        const wrLast = calc.wr[calc.wr.length - 1]!; if (wrLast !== undefined) add('WilliamsR', wrLast, wrLast < -80 ? 'buy' : wrLast > -20 ? 'sell' : 'hold');
        const adxLast = calc.adx[calc.adx.length - 1]; if (adxLast) add('ADX', adxLast.adx, adxLast.pdi > adxLast.mdi ? 'buy' : 'sell', 0.5, Math.min(1, adxLast.adx / 50));
        const cciLast = calc.cci[calc.cci.length - 1]!; add('CCI20', cciLast, cciLast < -100 ? 'buy' : cciLast > 100 ? 'sell' : 'hold');
        const rocLast = calc.roc[calc.roc.length - 1]!; add('ROC9', rocLast, rocLast > 0 ? 'buy' : rocLast < 0 ? 'sell' : 'hold');
        const trixLast = calc.trix[calc.trix.length - 1]!; add('TRIX15', trixLast, trixLast > 0 ? 'buy' : trixLast < 0 ? 'sell' : 'hold');

        // Volatility/Channels
        const bbLast = calc.bb[calc.bb.length - 1]; if (bbLast) add('Bollinger', lastClose, lastClose <= bbLast.lower ? 'buy' : lastClose >= bbLast.upper ? 'sell' : 'hold');
        const atrLast = calc.atr14[calc.atr14.length - 1]!; add('ATR14', atrLast, 'hold', 0.2, 1);
        const kcLast = calc.kc[calc.kc.length - 1]; if (kcLast) add('Keltner', lastClose, lastClose <= kcLast.lower ? 'buy' : lastClose >= kcLast.upper ? 'sell' : 'hold');

        // Volume-based
        const mfiLast = calc.mfi[calc.mfi.length - 1]!; add('MFI14', mfiLast, mfiLast < 20 ? 'buy' : mfiLast > 80 ? 'sell' : 'hold');
        const obvLast = calc.obv[calc.obv.length - 1]!; add('OBV', obvLast, 'hold', 0.3, 1);

        // Trend systems
        const psarLast = calc.psar[calc.psar.length - 1]!; add('PSAR', psarLast, psarLast < lastClose ? 'buy' : 'sell');
        const ichiLast = calc.ichimoku[calc.ichimoku.length - 1]; if (ichiLast) add('Ichimoku', lastClose, lastClose > ichiLast.spanA && lastClose > ichiLast.spanB ? 'buy' : 'sell');

		// Evaluate simple accuracy over window of 50 bars
		const horizon = 3;
		const window = Math.min(50, calc.closes.length - horizon - 1);
		const accuracy: Record<string, number> = {};
		const evaluatedCount: Record<string, number> = {};
		const sign = (x: number) => (x > 0 ? 1 : x < 0 ? -1 : 0);
		for (let i = calc.closes.length - window - 1; i < calc.closes.length - horizon; i++) {
			const futureDelta = calc.closes[i + horizon] - calc.closes[i];
			const addEval = (id: string, s: 'buy'|'sell'|'hold') => {
				if (!evaluatedCount[id]) { evaluatedCount[id] = 0; accuracy[id] = 0; }
				evaluatedCount[id]++;
				const dir = s === 'buy' ? 1 : s === 'sell' ? -1 : 0;
				if (dir !== 0 && dir === sign(futureDelta)) accuracy[id]++;
			};
			// Reproduce signals at index i
			addEval('EMA20_vs_SMA20', calc.ema20[i] > calc.sma20[i] ? 'buy' : 'sell');
			const rsi = calc.rsi14[i]; addEval('RSI14', rsi < 30 ? 'buy' : rsi > 70 ? 'sell' : 'hold');
			const m = calc.macd[i]; if (m && m.MACD !== undefined && m.signal !== undefined) addEval('MACD', m.MACD > m.signal ? 'buy' : 'sell');
			const st = calc.stoch[i]; if (st) addEval('Stochastic', st.k > st.d ? 'buy' : 'sell');
			const w = calc.wr[i]; if (w !== undefined) addEval('WilliamsR', w < -80 ? 'buy' : w > -20 ? 'sell' : 'hold');
			const adx = calc.adx[i]; if (adx) addEval('ADX', adx.pdi > adx.mdi ? 'buy' : 'sell');
			const cci = calc.cci[i]; addEval('CCI20', cci < -100 ? 'buy' : cci > 100 ? 'sell' : 'hold');
			const r = calc.roc[i]; addEval('ROC9', r > 0 ? 'buy' : r < 0 ? 'sell' : 'hold');
			const tr = calc.trix[i]; addEval('TRIX15', tr > 0 ? 'buy' : tr < 0 ? 'sell' : 'hold');
			const bb = calc.bb[i]; if (bb) addEval('Bollinger', calc.closes[i] <= bb.lower ? 'buy' : calc.closes[i] >= bb.upper ? 'sell' : 'hold');
			const kc = calc.kc[i]; if (kc) addEval('Keltner', calc.closes[i] <= kc.lower ? 'buy' : calc.closes[i] >= kc.upper ? 'sell' : 'hold');
			const ps = calc.psar[i]; addEval('PSAR', ps < calc.closes[i] ? 'buy' : 'sell');
		}
		const accuracyRatio: Record<string, number> = { ...storedAccuracies };
		Object.keys(evaluatedCount).forEach((id) => {
			accuracyRatio[id] = evaluatedCount[id] ? accuracy[id] / evaluatedCount[id] : 0;
		});
		// Filter indicators by accuracy threshold with minimum active size
		const threshold = 0.55;
		const sorted = Object.entries(accuracyRatio).sort((a, b) => b[1] - a[1]);
		const activeSet = new Set(sorted.filter(([_, acc]) => acc >= threshold).slice(0, 20).map(([id]) => id));
		const filtered = results.filter(r => activeSet.has(r.indicatorId));
		// Weight by accuracy (0.5..1.0) and any provided confidence
		const base = (filtered.length ? filtered : results);
		const weighted = base.map(r => ({
			...r,
			weight: (0.5 + (accuracyRatio[r.indicatorId] ?? 0) * 0.5) * (r.confidence ?? 1),
		}));
		const agg = aggregateSignals(weighted);
		return { buy: agg.buy, sell: agg.sell, hold: agg.hold, predictedPrice: lastClose, indicatorResults: weighted, _accuracy: accuracyRatio, _activeCount: base.length } as any;
    }, [calc, storedAccuracies]);

	useEffect(() => {
        if (!prediction || points.length === 0) return;
		const payload = {
			timestamp: Date.now(),
			asset: DEFAULT_CONFIG.asset.symbol,
			timeframe: 3,
            signals: { buy: prediction.buy, sell: prediction.sell, hold: prediction.hold },
            predictedPrice: prediction.predictedPrice,
            indicatorResults: prediction.indicatorResults,
		};
		postPrediction(payload).catch(() => void 0);
		// send stats snapshot
		if ((prediction as any)._accuracy) {
			postIndicatorStats({ indicators: (prediction as any)._accuracy }).catch(() => void 0);
		}
		setLastPredictionAt(payload.timestamp);
	}, [prediction, points]);

	return (
		<div className="traid-new-container">
			<h2>TraidNew - Trading Analytics</h2>
			{loading && <p>Loading EUR/USD 1m…</p>}
            {error && <p className="error">{error}</p>}
			{points.length > 0 && (
				<>
					<div className="panel">
						<AdvancedRealTimeChart
							width="100%"
							height={420}
							symbol="EURUSD"
							theme="dark"
							interval="1"
							hide_top_toolbar
							hide_legend
						/>
					</div>
					{prediction && (
						<div className="panel signal-row">
							<strong>3m Signal (active: {(prediction as any)._activeCount || 0}):</strong>
                            {(() => {
                                const entries = [
                                    { id: 'buy', label: 'BUY', value: prediction.buy, cls: 'chip chip--buy' },
                                    { id: 'sell', label: 'SELL', value: prediction.sell, cls: 'chip chip--sell' },
                                    { id: 'hold', label: 'HOLD', value: prediction.hold, cls: 'chip chip--hold' },
                                ];
                                const max = Math.max(...entries.map(e => e.value));
                                return (
                                    <>
                                        {entries.map(e => (
                                            <span key={e.id} className={`${e.cls} ${e.value === max ? 'chip--highlight' : ''}`}>
                                                {e.label}: {e.value.toFixed(1)}%
                                            </span>
                                        ))}
                                    </>
                                );
                            })()}
                        </div>
                    )}
					{prediction && (
						<div className="panel panel-margin-top">
							<strong>Indicator stats (last 50 bars):</strong>
							<table>
								<thead>
									<tr><th>Indicator</th><th>Accuracy</th></tr>
								</thead>
								<tbody>
									{Object.entries((prediction as any)._accuracy || {})
										.sort((a,b) => (b[1] as number) - (a[1] as number))
										.slice(0, 15)
										.map(([id, acc]) => (
											<tr key={id}><td>{id}</td><td>{((acc as number) * 100).toFixed(1)}%</td></tr>
										))}
								</tbody>
							</table>
						</div>
					)}
					{lastPredictionAt > 0 && (
						<div className="panel panel-margin-small">
							<em>Last prediction at: {new Date(lastPredictionAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}</em>
						</div>
					)}
					<div className="panel">
						<p>
							<strong>Data source:</strong> Alpha Vantage FX (UTC, mid price). Bars used for analysis: {calc ? calc.closes.length : 0} of {points.length} available.
						</p>
					<p className="muted">Times shown in your local timezone. Updated: {lastUpdated ? new Date(lastUpdated).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '—'}</p>
						<table>
							<thead>
								<tr>
									<th>Time (UTC)</th>
									<th>Open</th>
									<th>High</th>
									<th>Low</th>
									<th>Close</th>
								</tr>
							</thead>
							<tbody>
								{points.slice(-100).reverse().map((p) => (
									<tr key={p.timestamp}>
										<td>{new Date(p.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</td>
										<td>{p.open.toFixed(5)}</td>
										<td>{p.high.toFixed(5)}</td>
										<td>{p.low.toFixed(5)}</td>
										<td>{p.close.toFixed(5)}</td>
									</tr>
								))}
							</tbody>
						</table>
					</div>
				</>
			)}
		</div>
	);
}

