import type { IndicatorResult } from '../../../../shared/traidNew/types/prediction';

export function aggregateSignals(indicatorResults: IndicatorResult[]) {
	let buy = 0;
	let sell = 0;
	let hold = 0;
	let total = 0;

	for (const r of indicatorResults) {
		const w = r.weight * (r.confidence ?? 1);
		total += w;
		if (r.signal === 'buy') buy += w;
		else if (r.signal === 'sell') sell += w;
		else hold += w;
	}

	const norm = total || 1;
	return {
		buy: (buy / norm) * 100,
		sell: (sell / norm) * 100,
		hold: (hold / norm) * 100,
		confidence: Math.min(1, total / Math.max(1, indicatorResults.length)),
	};
}

