import axios from 'axios';

const baseURL = process.env.REACT_APP_BACKEND_URL || 'http://localhost:4000';

export const api = axios.create({ baseURL });

export async function fetchForexIntraday(params: { symbol?: string; interval?: '1min' | '5min' }) {
	const res = await api.get('/api/forex/intraday', { params });
	return res.data as { symbol: string; interval: string; points: Array<{ timestamp: number; open: number; high: number; low: number; close: number; volume: number; symbol: string }>; };
}

export async function postPrediction(prediction: any) {
	await api.post('/api/prediction', prediction);
}

export async function postIndicatorStats(update: any) {
	await api.post('/api/indicators/stats', update);
}

export async function getIndicatorStats() {
    const res = await api.get('/api/indicators/stats');
    return res.data as { indicators: Record<string, number>; lastUpdated: number };
}

